test.describe('SSR rendering — all blocks', () => {

  test('all wrapper-animated blocks SSR-render without JS errors', async ({ browser }) => {
    const context = await browser.newContext({ javaScriptEnabled: false })
    const page = await context.newPage()
    await page.goto('/')
    // Verify no 500 on the page
    const title = await page.title()
    expect(title).not.toContain('500')
    await context.close()
  })

  test('home page SSR renders wrapper blocks', async ({ browser }) => {
    const context = await browser.newContext({ javaScriptEnabled: false })
    const page = await context.newPage()
    await page.goto('/')
    { const el = page.locator('.block-activities').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // activities
    { const el = page.locator('.block-bienvenue').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // bienvenue
    { const el = page.locator('.block-contact').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // contact
    { const el = page.locator('.block-equipe').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // equipe
    { const el = page.locator('.block-evenements').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // evenements
    { const el = page.locator('.block-faq').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // faq
    { const el = page.locator('.block-full-width-image').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // fullWidthImage
    { const el = page.locator('.block-gallery').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // gallery
    { const el = page.locator('.block-icon-grid').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // iconGrid
    { const el = page.locator('.block-inscription-alpha').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // inscriptionAlpha
    { const el = page.locator('.block-louange').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // louange
    { const el = page.locator('.block-quote').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // quote
    { const el = page.locator('.block-rich-text').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // richText
    { const el = page.locator('.block-stats').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // stats
    { const el = page.locator('.block-text-image').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // textImage
    { const el = page.locator('.vision-section').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // vision
    { const el = page.locator('.block-youtube').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // youtube
    await context.close()
  })

  test('internally animated blocks SSR-render on home page', async ({ browser }) => {
    const context = await browser.newContext({ javaScriptEnabled: false })
    const page = await context.newPage()
    await page.goto('/')
    { const el = page.locator('.aspirations-viewport').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // aspirations
    { const el = page.locator('.block-footer').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // footer
    { const el = page.locator('.block-nous-rejoindre').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // nousRejoindre
    { const el = page.locator('.block-rejoins').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // rejoins
    await context.close()
  })

  test('messages page SSR renders without errors', async ({ browser }) => {
    const context = await browser.newContext({ javaScriptEnabled: false })
    const page = await context.newPage()
    await page.goto('/messages')
    const title = await page.title()
    expect(title).not.toContain('500')
    await context.close()
  })

  test('contact page SSR renders without errors', async ({ browser }) => {
    const context = await browser.newContext({ javaScriptEnabled: false })
    const page = await context.newPage()
    await page.goto('/contact')
    const title = await page.title()
    expect(title).not.toContain('500')
    await context.close()
  })

  test('no 500 errors on any page without JS', async ({ browser }) => {
    const pages = ['/', '/contact', '/messages', '/event-list', '/agenda']
    const context = await browser.newContext({ javaScriptEnabled: false })
    for (const path of pages) {
      const page = await context.newPage()
      await page.goto(path)
      const title = await page.title()
      expect(title, `${path}: page error`).not.toContain('500')
      await page.close()
    }
    await context.close()
  })
})

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 3: Hydration (no console errors)
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Hydration — all blocks', () => {

  test('home page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    page.on('console', msg => {
      if (msg.type() === 'error') errors.push(msg.text())
    })
    await page.goto('/')
    await page.waitForTimeout(2000)
    const criticalErrors = errors.filter(e =>
      !e.includes('favicon') &&
      !e.includes('Failed to load resource') &&
      !e.includes('404')
    )
    expect(criticalErrors).toEqual([])
  })

  test('contact page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    await page.goto('/contact')
    await page.waitForTimeout(2000)
    const title = await page.title()
    expect(title).not.toContain('500')
    expect(errors.filter(e => !e.includes('favicon'))).toEqual([])
  })

  test('messages page loads without console errors', async ({ page }) => {
    const errors: string[] = []
    page.on('pageerror', err => errors.push(err.message))
    await page.goto('/messages')
    await page.waitForTimeout(2000)
    expect(errors.filter(e => !e.includes('favicon'))).toEqual([])
  })

  test('all pages load without 500 errors', async ({ page }) => {
    const pages = ['/', '/contact', '/messages', '/event-list', '/agenda']
    for (const path of pages) {
      const errors: string[] = []
      page.on('pageerror', err => errors.push(err.message))
      await page.goto(path)
      await page.waitForTimeout(2000)
      const title = await page.title()
      expect(title, `${path}: 500 error`).not.toContain('500')
      expect(errors, `${path}: page errors`).toEqual([])
    }
  })
})

