// SECTION 5: Responsive tests
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Responsive — all blocks', () => {

  test('device toggle buttons exist in admin mode', async ({ page }) => {
    await page.goto('/?admin=true')
    await page.waitForTimeout(2000)
    await expect(page.locator('.device-btn')).toHaveCount(3)
  })

  test('narrow 320px viewport does not overflow', async ({ page }) => {
    await page.setViewportSize({ width: 320, height: 700 })
    await page.goto('/')
    await page.waitForTimeout(2000)
    const docWidth = await page.evaluate(() => document.documentElement.scrollWidth)
    const vpWidth = await page.evaluate(() => window.innerWidth)
    expect(docWidth).toBeLessThanOrEqual(vpWidth + 1)
  })

  test('wide 1440px viewport renders key blocks', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 })
    await page.goto('/')
    await page.waitForTimeout(2000)
    { const el = page.locator('.block-activities').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // activities
    { const el = page.locator('.aspirations-viewport').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // aspirations
    { const el = page.locator('.block-bandeau').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // bandeau
    { const el = page.locator('.block-bienvenue').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // bienvenue
    { const el = page.locator('.block-contact').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // contact
    { const el = page.locator('.block-equipe').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // equipe
    { const el = page.locator('.block-evenements').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // evenements
    { const el = page.locator('.block-faq').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // faq
  })

  test('mobile 375px viewport renders blocks', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 })
    await page.goto('/')
    await page.waitForTimeout(2000)
    { const el = page.locator('.block-activities').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // activities
    { const el = page.locator('.aspirations-viewport').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // aspirations
    { const el = page.locator('.block-bandeau').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // bandeau
    { const el = page.locator('.block-bienvenue').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // bienvenue
    { const el = page.locator('.block-contact').first(); if (await el.count()) await expect(el).toBeVisible({ timeout: 5000 }) } // contact
  })
})

// ═══════════════════════════════════════════════════════════════════════════
// SECTION 6: Cross-block integration
// ═══════════════════════════════════════════════════════════════════════════

test.describe('Cross-block integration', () => {

  test('all 24 block types are registered', () => {
    const registeredTypes = Object.keys(BLOCK_TYPES)
    expect(registeredTypes.length).toBe(24)
  })

  test('blocks span at least 2 categories', () => {
    const categories = new Set(Object.values(BLOCK_TYPES).map(d => d.category))
    expect(categories.size).toBeGreaterThanOrEqual(2)
  })

  test('blocks span at least 2 animation strategies', () => {
    const strategies = new Set(Object.values(BLOCK_TYPES).map(d => d.animations))
    expect(strategies.size).toBeGreaterThanOrEqual(2)
  })

  test('at least one block uses array type', () => {
    const hasArray = Object.entries(BLOCK_TYPES).some(([_, def]) =>
      def.schema.some((f: any) => f.type === 'array')
    )
    expect(hasArray).toBe(true)
  })

  test('at least one block uses each major field type', () => {
    const usedTypes = new Set<string>()
    for (const def of Object.values(BLOCK_TYPES)) {
      for (const field of def.schema) {
        usedTypes.add(field.type)
      }
    }
    expect(usedTypes.has('text')).toBe(true)
    expect(usedTypes.has('animation')).toBe(true)
    expect(usedTypes.has('color')).toBe(true)
  })
})
